from robot.api import logger
from ta_egate_cmd_parser.command_getter import get
from ta_egate_cmd_parser.egate_connection_registry import add_to_registry, remove_from_registry
from ta_egate_cmd_parser.egate_generic_wait4 import create_event, wait_for_event_finish, destroy_event, destroy_all_events


class EgateCmdParser(object):
    """
    Library which allows to execute EPCSIM commands.
    """

    def __init__(self):
        """

        :return:
        """
        pass

    def add_egate_connection_parameters(self, egate_id, host, port):
        """
        Add new egate connection params.
        Default egate connection params: egate_id=0, host='localhost', port=20000 are added at init.

        :param egate_id: id
        :param host: ip address of machine where EPCSIM is started
        :param port: egate port
        :return:

        +---------------------------------+------------+---------------+------------+
        | Usage from Robot                                                          |
        +=================================+============+===============+============+
        | Add egate connection parameters   egate_id=1   host=10.0.1.1   port=30000 |
        +---------------------------------+------------+---------------+------------+
        """
        logger.info('Adding EGATE host IP address: {} and port: {} with egate_id: {} to registry'.format(host, port, egate_id))
        add_to_registry(egate_id=egate_id, egate_host=host, egate_port=int(port))

    def remove_egate_connection(self, egate_id=0):
        """
        Remove egate connection.
        Default egate connection params: egate_id=0 is added at init.

        :param egate_id: id
        :return:

        +--------------------------+------------+
        | Usage from Robot                      |
        +==========================+============+
        | Remove egate connection    egate_id=1 |
        +--------------------------+------------+
        """
        remove_from_registry(egate_id=egate_id)

    def get_command(self, command_name):
        """
        Returns command class

        :param command_name: epcsim command name
        :return:
        """
        return get(command_name)

    def run_command(self, name, egate_id=0, **kwargs):
        """
        Run executable command directly from robot script

        :param name: epcsim command name that is already implemented
        :param kwargs: params of command as given in epcsim
        :return:
        """
        name = str(name)
        cmd_cls = get(name)
        try:
            cmd_instance = cmd_cls(**kwargs)
        except TypeError:
            cmd_instance = cmd_cls(name, **kwargs)
        # to do - verify that command is not parsable (does not have *parse* metchod)
        # or any classmethod to create instance
        status, output = cmd_instance.execute(egate_id)
        return status

    def wait_for_egate_regexp(self, regexp, timeout, egate_id=0):
        """
        Opens egate connection and waits for specific regexp to pass untill timeout.
        Command is blocking.
        Raises EventDoesNotOccur on timeout.

        :param regexp: regexp string (not re object)
        :param timeout:
        :return:
        """
        event = create_event(regexp=regexp,
                             timeout=timeout,
                             egate_id=egate_id)
        wait_for_event_finish(event)

    def execute_on_egate_output(self, regexp, timeout, callback, cyclic=False, egate_id=0):
        """
        Opens egate connection and waits for specific regexp to pass untill timeout. If regexp passes,
        callback will be executed.
        Command is non-blocking.
        Callback execution failure will be catched but will not fail the testcase when not handled.
        Cyclic callback execution can be enabled. Cyclic event must be manually stopped with 'cancel event'.
        Because of callback in-use, it is suggested to use it from python only.

        :param regexp: regexp string (not re object)
        :param timeout:
        :param callback: callback function
        :param cyclic: True/False
        :return: commands status: OK, TIMEOUT, CALLBACK_FAILURE
        """
        event = create_event(regexp=regexp,
                             timeout=timeout,
                             callback=callback,
                             cyclic=cyclic,
                             egate_id=egate_id)
        return event

    def cancel_event(self, event):
        """
        Cancels the event, must wait for event end.
        Command is blocking.
        It does not raise in case of event timeouts/callback errors.

        :param event:
        :return:
        """
        destroy_event(event)

    def cancel_all_events(self):
        """
        Cancels all configured events, must wait for each event end before proceeding.
        Command is blocking.
        It does not raise in case of event timeouts/callback errors.

        :return:
        """
        destroy_all_events()
